import { z } from 'zod'

// Mirror of shared/manifest.schema.json (generated by backend pydantic models).
// manifest.test.ts checks key-for-key parity; change both sides together.

export const TUMOR_IDS = ['tumor_et', 'tumor_ncr', 'tumor_ed'] as const
export type TumorId = (typeof TUMOR_IDS)[number]
/** Value written into mask_u8.bin for each tumour asset (MSD convention). */
export const LABEL_BY_TUMOR: Record<TumorId, 1 | 2 | 3> = { tumor_et: 3, tumor_ncr: 2, tumor_ed: 1 }
export const PROVENANCES = ['ground-truth', 'monai-segresnet', 'synthetic'] as const
export type Provenance = (typeof PROVENANCES)[number]

const Vec3Schema = z.tuple([z.number(), z.number(), z.number()])
const Mat4Schema = z.array(z.number()).length(16)
const CaseIdSchema = z.string().regex(/^[a-z0-9_]+$/)

export const SurfaceAssetSchema = z.strictObject({
  id: z.literal('brain_surface'),
  node: z.string(),
  kind: z.literal('surface'),
})

export const TumorAssetSchema = z.strictObject({
  id: z.enum(TUMOR_IDS),
  label: z.union([z.literal(1), z.literal(2), z.literal(3)]),
  node: z.string(),
  kind: z.literal('tumor'),
  color: z.string().regex(/^#[0-9A-Fa-f]{6}$/),
  volume_ml: z.number().min(0),
  centroid_ras: Vec3Schema,
  bbox_ras: z.tuple([Vec3Schema, Vec3Schema]),
  min_dist_surface_mm: z.number().min(0),
})

export const VolumesSchema = z.strictObject({ flair: z.string(), mask: z.string() })

export const MetricsSchema = z.strictObject({
  dice_vs_gt: z.record(z.string(), z.number()).nullable().default(null),
})

export const ManifestShape = z.strictObject({
  case_id: CaseIdSchema,
  provenance: z.enum(PROVENANCES),
  dims: z.tuple([z.int().min(1), z.int().min(1), z.int().min(1)]),
  vox2ras: Mat4Schema,
  ras2gl: Mat4Schema,
  midline_x_ras: z.number(),
  volumes: VolumesSchema,
  glb: z.string(),
  assets: z.array(z.discriminatedUnion('kind', [SurfaceAssetSchema, TumorAssetSchema])),
  metrics: MetricsSchema,
})

/** ManifestShape plus the cross-field rules the backend enforces in pydantic validators. */
export const ManifestSchema = ManifestShape.superRefine((m, ctx) => {
  const ids = m.assets.map((a) => a.id)
  if (ids.filter((id) => id === 'brain_surface').length !== 1) {
    ctx.addIssue({ code: 'custom', path: ['assets'], message: 'assets must contain exactly one brain_surface' })
  }
  if (new Set(ids).size !== ids.length) {
    ctx.addIssue({ code: 'custom', path: ['assets'], message: 'asset ids must be unique' })
  }
  m.assets.forEach((a, i) => {
    if (a.kind === 'tumor' && LABEL_BY_TUMOR[a.id] !== a.label) {
      ctx.addIssue({ code: 'custom', path: ['assets', i, 'label'], message: `label ${a.label} does not match ${a.id}` })
    }
  })
})

export const CaseIndexEntrySchema = z.strictObject({
  case_id: CaseIdSchema,
  provenance: z.enum(PROVENANCES),
  path: z.string(),
})

export const CaseIndexSchema = z.strictObject({ cases: z.array(CaseIndexEntrySchema) })

export type Vec3 = [number, number, number]
export type Manifest = z.infer<typeof ManifestSchema>
export type SurfaceAsset = z.infer<typeof SurfaceAssetSchema>
export type TumorAsset = z.infer<typeof TumorAssetSchema>
export type Asset = SurfaceAsset | TumorAsset
export type CaseIndex = z.infer<typeof CaseIndexSchema>
export type CaseIndexEntry = z.infer<typeof CaseIndexEntrySchema>

export function tumorAssets(m: Manifest): TumorAsset[] {
  return m.assets.filter((a): a is TumorAsset => a.kind === 'tumor')
}

export function assetById(m: Manifest, id: string): Asset | undefined {
  return m.assets.find((a) => a.id === id)
}

/** RAS: +x points to the patient's right, so x below the midline is the left hemisphere. */
export function hemisphereOf(x: number, midlineX: number): 'left' | 'right' | 'midline' {
  if (x < midlineX) return 'left'
  if (x > midlineX) return 'right'
  return 'midline'
}

export function formatIssues(error: z.ZodError): string {
  return error.issues
    .map((i) => `${i.path.length ? i.path.map(String).join('.') : '(root)'}: ${i.message}`)
    .join('; ')
}
